BEGIN TRANSACTION;
CREATE TABLE "channels" (
"Channel_Name" TEXT,
  "Client_Name" TEXT
);
CREATE TABLE "clients" (
"Client_Name" TEXT
);
CREATE TABLE "created_assets" (
"Asset_ID" INTEGER,
  "Video_ID" INTEGER,
  "Output_Type" TEXT,
  "Create_Date" TEXT,
  "Created_Duration" INTEGER
);
CREATE TABLE "post_distribution" (
"Post_ID" INTEGER,
  "Channel_Name" TEXT,
  "Published_Platform" TEXT,
  "Published_URL" TEXT
);
CREATE TABLE "published_posts" (
"Post_ID" INTEGER,
  "Asset_ID" INTEGER,
  "Publish_Date" TEXT,
  "Published_Duration" INTEGER
);
CREATE TABLE "raw_video_channel" (
"Video_ID" INTEGER,
  "Channel_Name" TEXT
);
CREATE TABLE "raw_videos" (
"Video_ID" INTEGER,
  "User_ID" INTEGER,
  "Headline" TEXT,
  "Source_URL" TEXT,
  "Upload_Date" TEXT,
  "Input_Type" TEXT,
  "Language" TEXT,
  "Uploaded_Duration" INTEGER
);
CREATE TABLE "users" (
"User_ID" INTEGER,
  "User_Name" TEXT,
  "Team_Name" TEXT,
  "Client_Name" TEXT
);
COMMIT;
